import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import CountryList from "@/JsonFiles/CountryList.json";
import { asset_config_create_list_update_locations } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    locationViewDialog: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      center: {
        lat: 45.508,
        lng: -73.587
      },
      markers: [],
      places: [],
      currentPlace: null,
      loading1: false,
      countryitems: [],
      search: "",
      locationAddress: "",
      locationState: "",
      geoLongitude: "",
      districtItems: [],
      geoLattitude: "",
      countryData: "",
      locationPincode: "",
      locationDistrict: "",
      loading: false,
      defaultCenter: {
        lat: 0,
        lng: 0
      }
    };
  },
  watch: {
    locationViewDialog: {
      async handler() {
        if (this.locationViewDialog == true) {
          this.fetch_details();
          if (this.rowInfo.geo_lat != null && this.rowInfo.geo_long != null) {
            this.locationPincode = this.rowInfo.asset_location_pincode == null || this.rowInfo.asset_location_pincode == undefined || this.rowInfo.asset_location_pincode == 0 ? "" : this.rowInfo.asset_location_pincode;
            if (this.locationPincode != "") {
              this.fetchPinData();
            }
            this.countryData = this.rowInfo.asset_location_country == null ? "" : this.rowInfo.asset_location_country;
            this.locationState = this.rowInfo.asset_location_state == null ? "" : this.rowInfo.asset_location_state;
            this.locationDistrict = this.rowInfo.asset_location_district == null ? "" : this.rowInfo.asset_location_district;
            this.locationAddress = this.rowInfo.asset_location_address == null ? "" : this.rowInfo.asset_location_address;
            this.geoLattitude = this.rowInfo.geo_lat;
            this.geoLongitude = this.rowInfo.geo_long;
            this.markers = [];
            var marker = {
              lat: Number(this.rowInfo.geo_lat),
              lng: Number(this.rowInfo.geo_long)
            };
            this.markers.push({
              position: marker
            });
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_details() {
      CountryList.forEach(element => {
        this.countryitems.push({
          name: element.name,
          code: element.name
        });
      });
    },
    is_Number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    async fetchPinData() {
      this.stateItems = [];
      this.districtItems = [];
      // Reset any previous errors
      if (!this.locationPincode) {
        this.$emit("errorMsg", "Please enter a Postal Index Number");
        // this.error = "Please enter a Postal Index Number";
        return;
      }
      this.loading1 = true;
      try {
        const response = await fetch(`https://api.postalpincode.in/pincode/${this.locationPincode}`); // Replace with your API URL
        if (!response.ok) {
          this.$emit("errorMsg", "Failed to fetch data");
          throw new Error("Failed to fetch data");
        }
        this.loading1 = false;
        const data = await response.json();
        var masterArray = data[0].PostOffice;
        masterArray.forEach(element => {
          this.stateItems.push(element.State);
          this.districtItems.push(element.District);
        });
        this.locationDistrict = data[0].PostOffice[0].District;
        this.locationState = data[0].PostOffice[0].State;
      } catch (err) {
        this.loading1 = false;
        this.error = err.message;
        this.locationPincode = "";
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    setPlace(place) {
      this.currentPlace = place;
    },
    clearField() {
      this.search = null;
      this.add_Marker();
    },
    add_Marker() {
      this.markers = [];
      var marker = {
        lat: this.currentPlace.geometry.location.lat(),
        lng: this.currentPlace.geometry.location.lng()
      };
      this.markers.push({
        position: marker
      });
      this.geoLattitude = marker.lat;
      this.geoLongitude = marker.lng;
    },
    callposition(latLng) {
      this.markers = [];
      var marker = {
        lat: latLng.latLng.lat(),
        lng: latLng.latLng.lng()
      };
      this.markers.push({
        position: marker
      });
      this.geoLattitude = marker.lat;
      this.geoLongitude = marker.lng;
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.edit_location_view();
      }
    },
    async edit_location_view() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_config_create_list_update_locations, {
          input: {
            organization_id: data.organization.organization_id,
            action_type: "UPDATE",
            asset_location_status: "ACTIVE",
            asset_location_id: this.rowInfo.asset_location_id,
            asset_location_lat: this.geoLattitude,
            asset_location_long: this.geoLongitude,
            asset_location_state: this.locationState,
            asset_location_district: this.countryData == "India" ? this.locationDistrict : "",
            asset_location_country: this.countryData,
            asset_location_pincode: this.countryData == "India" ? Number(this.locationPincode) : 0,
            asset_location_address: this.locationAddress
          }
        }));
        var response = JSON.parse(result.data.asset_config_create_list_update_locations);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.$emit("successMsg", response.Message);
        } else {
          this.loading = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
